 $tests['External creator from zero supports current INSERT']=function(){global$wpdb;mysqli_report(MYSQLI_REPORT_OFF);$db=new mysqli('eipsi-m0-db',DB_USER,DB_PASSWORD,'m8_external');m8_check(!$db->connect_error,'External fixture connection');$table=$wpdb->prefix.'vas_form_results';try{m8_check(EIPSI_External_Schema_Adapter::create_results($db),'External create');$cols=[];$r=$db->query("SHOW COLUMNS FROM `$table`");while($row=$r->fetch_assoc())$cols[]=$row['Field'];foreach(['browser','os','screen_width']as$c)m8_check(in_array($c,$cols,true),'External missing '.$c);$store=new class extends EIPSI_Storage_External_Submission_Store{public function get_connection(){return new mysqli('eipsi-m0-db',DB_USER,DB_PASSWORD,'m8_external');}};$data=['form_id'=>'hist','participant_id'=>'hist','session_id'=>'hist','survey_id'=>88001,'wave_index'=>1,'user_fingerprint'=>'hist','form_name'=>'M8 historical','created_at'=>'2020-02-03 04:05:06','submitted_at'=>null,'ip_address'=>null,'device'=>null,'browser'=>'fixture','os'=>'fixture','screen_width'=>640,'duration'=>1,'duration_seconds'=>1.0,'start_timestamp_ms'=>1,'end_timestamp_ms'=>2,'metadata'=>'{}','status'=>'submitted','form_responses'=>'{"answer":"preserve"}'];$r=$store->insert_form_submission($data);m8_check($r['success']&&$r['insert_id']>0,'External INSERT '.wp_json_encode($r));$row=$db->query("SELECT * FROM `$table`")->fetch_assoc();m8_check($row['form_responses']===$data['form_responses'],'External value changed');$check=new ReflectionMethod($store,'validate_required_columns');m8_check($check->invoke($store,$db,$table)['success'],'External verify');$db->query("ALTER TABLE `$table` DROP COLUMN browser, DROP COLUMN os, DROP COLUMN screen_width");m8_check(EIPSI_External_Schema_Adapter::ensure_required_columns($db,$table),'External legacy safe additions');m8_check($store->insert_form_submission($data)['success'],'External existing insert');m8_check((int)$db->query("SELECT COUNT(*) FROM `$table`")->fetch_row()[0]===2,'External data 